try:
    import numpy as np
    anomalies = []
    total = 0
    for col in num_cols:
        if total >= 25:
            break
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        shift = 0
        if s.min() < 0:
            shift = -s.min()
        if abs(skew) > 2:
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
        Q1, Q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        IQR = Q3 - Q1
        lo_t, hi_t = Q1 - 3*IQR, Q3 + 3*IQR
        mask = (s_t < lo_t) | (s_t > hi_t)
        flagged_frac = mask.sum() / len(s_t)
        if flagged_frac > 0.05:
            anomalies.append({
                "column": col, "row_index": None, "value": None,
                "expected_range": f"heavy-tailed distribution",
                "severity": "low",
                "explanation": f"{col} is heavy-tailed; extreme values are natural, not flagged"
            })
            total += 1
            continue
        if abs(skew) > 2:
            lo_orig = float(np.expm1(lo_t) - shift)
            hi_orig = float(np.expm1(hi_t) - shift)
        else:
            lo_orig = float(lo_t)
            hi_orig = float(hi_t)
        flagged_idx = s_t[mask].index.tolist()
        for idx in flagged_idx:
            if total >= 25:
                break
            val = float(df.loc[idx, col])
            s_val = s_t.loc[idx]
            if abs(skew) > 2:
                if s_val > Q3 + 5*IQR:
                    sev = "critical"
                elif s_val > Q3 + 4*IQR:
                    sev = "high"
                else:
                    sev = "medium"
            else:
                if val > Q3 + 5*IQR or val < Q1 - 5*IQR:
                    sev = "critical"
                elif val > Q3 + 4*IQR or val < Q1 - 4*IQR:
                    sev = "high"
                else:
                    sev = "medium"
            exp_range = f"[{lo_orig:.2f}, {hi_orig:.2f}]"
            anomalies.append({
                "column": col, "row_index": int(idx), "value": val,
                "expected_range": exp_range, "severity": sev,
                "explanation": f"{col} value {val} lies outside expected range {exp_range}"
            })
            total += 1
    result['anomalies'] = anomalies
except Exception:
    pass

