    import numpy as np
    df['order_date'] = pd.to_datetime(df['order_date'])
    df['month'] = df['order_date'].dt.to_period('M')
    monthly_rev = df.groupby('month')['revenue'].sum().reset_index()
    monthly_rev['month_ts'] = monthly_rev['month'].apply(lambda x: x.start_time.timestamp())
    if len(monthly_rev) >= 3:
        x = monthly_rev['month_ts'].values
        y = monthly_rev['revenue'].values
        x_norm = (x - x.mean()) / x.std()
        coeffs = np.polyfit(x_norm, y, 1)
        last_period = monthly_rev['month'].iloc[-1]
        next_period = last_period + 1
        next_ts = next_period.start_time.timestamp()
        next_norm = (next_ts - x.mean()) / x.std()
        forecast_val = float(np.polyval(coeffs, next_norm))
        result['forecast_points'] = [{"period": str(next_period), "value": round(forecast_val, 2)}]
