import numpy as np
from scipy import stats

# EDA
try:
    metric_cols = ['left', 'tenure_months', 'salary', 'performance_score']
    for col in metric_cols:
        s = df[col].dropna()
        result['eda_summary'][col] = {
            'mean': float(s.mean()), 'std': float(s.std()),
            'min': float(s.min()), 'max': float(s.max()),
            'median': float(s.median()), 'count': int(s.count())
        }
except Exception:
    pass

# CORRELATIONS
try:
    num_cols = ['left', 'tenure_months', 'salary', 'performance_score']
    corr_matrix = df[num_cols].corr(method='pearson')
    for i, c1 in enumerate(num_cols):
        for c2 in num_cols[i+1:]:
            r = corr_matrix.loc[c1, c2]
            if abs(r) >= 0.2:
                result['correlations'][f'{c1}__{c2}'] = round(float(r), 4)
except Exception:
    pass

# SEGMENTATION by department
try:
    seg_col = 'department'
    top_depts = df[seg_col].value_counts().head(10).index.tolist()
    dff = df[df[seg_col].isin(top_depts)]
    for metric in ['left', 'tenure_months', 'salary', 'performance_score']:
        agg = dff.groupby(seg_col)[metric].mean()
        result['segments'].append({
            'segment_column': seg_col, 'metric_column': metric,
            'aggregation': 'mean', 'label': None,
            'results': [{'name': str(k), 'value': round(float(v), 4)} for k, v in agg.items()]
        })
    # attrition rate (left=1 share) per department
    agg_rate = dff.groupby(seg_col)['left'].mean()
    result['segments'].append({
        'segment_column': seg_col, 'metric_column': 'left',
        'aggregation': 'ratio', 'label': 'attrition_rate',
        'results': [{'name': str(k), 'value': round(float(v), 4)} for k, v in agg_rate.items()]
    })
    # count per department
    agg_cnt = dff.groupby(seg_col)['left'].count()
    result['segments'].append({
        'segment_column': seg_col, 'metric_column': 'left',
        'aggregation': 'count', 'label': None,
        'results': [{'name': str(k), 'value': int(v)} for k, v in agg_cnt.items()]
    })
except Exception:
    pass

# ANOMALIES
try:
    anomaly_cols = ['tenure_months', 'salary', 'performance_score', 'left']
    all_anomalies = []
    for col in anomaly_cols:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min())
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
            shift = 0
        Q1, Q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        IQR = Q3 - Q1
        lo3, hi3 = Q1 - 3*IQR, Q3 + 3*IQR
        lo4, hi4 = Q1 - 4*IQR, Q3 + 4*IQR
        lo5, hi5 = Q1 - 5*IQR, Q3 + 5*IQR
        mask = (s_t < lo3) | (s_t > hi3)
        flagged_frac = mask.sum() / len(s_t)
        if flagged_frac > 0.05:
            all_anomalies.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'[{float(s.quantile(0.25)):.2f}, {float(s.quantile(0.75)):.2f}]',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-value flagging skipped'
            })
            continue
        if abs(skew) > 2:
            lo3_orig = float(np.expm1(lo3) - shift)
            hi3_orig = float(np.expm1(hi3) - shift)
        else:
            lo3_orig, hi3_orig = float(lo3), float(hi3)
        exp_range = f'[{lo3_orig:.2f}, {hi3_orig:.2f}]'
        flagged_idx = s_t[mask].index.tolist()
        for idx in flagged_idx:
            raw_val = float(df.loc[idx, col])
            t_val = s_t.loc[idx]
            if t_val < lo5 or t_val > hi5:
                sev = 'critical'
            elif t_val < lo4 or t_val > hi4:
                sev = 'high'
            else:
                sev = 'medium'
            all_anomalies.append({
                'column': col, 'row_index': int(idx), 'value': raw_val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {raw_val} lies outside expected range {exp_range}'
            })
    all_anomalies.sort(key=lambda x: ['low','medium','high','critical'].index(x['severity']), reverse=True)
    result['anomalies'] = all_anomalies[:25]
except Exception:
    pass

# TRENDS (hire_date based)
try:
    df['hire_date_parsed'] = pd.to_datetime(df['hire_date'], errors='coerce')
    df['hire_ym'] = df['hire_date_parsed'].dt.to_period('M')
    monthly = df.groupby('hire_ym').agg(
        left_mean=('left', 'mean'),
        tenure_mean=('tenure_months', 'mean'),
        salary_mean=('salary', 'mean'),
        perf_mean=('performance_score', 'mean')
    ).sort_index()
    for col, key in [('left', 'left_mean'), ('tenure_months', 'tenure_mean'),
                     ('salary', 'salary_mean'), ('performance_score', 'perf_mean')]:
        series = monthly[key].dropna()
        if len(series) < 2:
            continue
        first_half = series.iloc[:len(series)//2].mean()
        second_half = series.iloc[len(series)//2:].mean()
        pct = float((second_half - first_half) / first_half * 100) if first_half != 0 else 0.0
        direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
        result['trends'].append({
            'column': col, 'period': 'MoM', 'direction': direction,
            'pct_change': round(pct, 4), 'segment': None
        })
except Exception:
    pass

# FORECASTING (salary simple linear trend)
try:
    df['hire_date_parsed'] = pd.to_datetime(df['hire_date'], errors='coerce')
    df['hire_ym'] = df['hire_date_parsed'].dt.to_period('M')
    sal_monthly = df.groupby('hire_ym')['salary'].mean().dropna()
    if len(sal_monthly) >= 6:
        x = np.arange(len(sal_monthly))
        y = sal_monthly.values
        slope, intercept, _, _, _ = stats.linregress(x, y)
        last_period = sal_monthly.index[-1]
        for i in range(1, 4):
            next_period = last_period + i
            pred = float(intercept + slope * (len(sal_monthly) - 1 + i))
            result['forecast_points'].append({'period': str(next_period), 'value': round(pred, 2)})
except Exception:
    pass

result['assumptions'] = [
    "Attrition rate computed as mean of binary 'left' column (1=left, 0=stayed).",
    "Trends computed over hire_date monthly cohorts, not calendar event dates.",
