    seg_metrics = [('Net Sales', 'sum'), ('Units', 'sum'), ('COGS', 'sum')]
    for seg_col in ['Dept', 'Region']:
        for metric, agg in seg_metrics:
            base = sale_rows if metric == 'Units' else sale_return_rows
            grp = base.groupby(seg_col)[metric].sum().nlargest(10)
            result['segments'].append({
