    for seg_col in ['Dept', 'Region']:
        base = sale_return_rows.groupby(seg_col).agg({'Net Sales': 'sum', 'COGS': 'sum'})
        base = base.nlargest(10, 'Net Sales')
        gm = ((base['Net Sales'] - base['COGS']) / base['Net Sales']).dropna()
        result['segments'].append({
