# Anomalies
try:
    import numpy as np
    anomaly_records = []
    for col in ['Net Sales', 'Units', 'COGS']:
        base = sale_rows[col].dropna() if col == 'Units' else sale_return_rows[col].dropna()
        skew = float(base.skew())
        shift = max(0, -base.min()) + 1 if base.min() < 0 else 0
        if abs(skew) > 2:
            vals = np.log1p(base + shift)
        else:
            vals = base.copy()
        q1, q3 = vals.quantile(0.25), vals.quantile(0.75)
        iqr = q3 - q1
        lo_ext, hi_ext = q1 - 3*iqr, q3 + 3*iqr
        flagged = vals[(vals < lo_ext) | (vals > hi_ext)]
        if len(flagged) / len(vals) > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': 'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme values are natural for this distribution'
            })
            continue
        orig_lo = float(np.expm1(lo_ext) - shift) if abs(skew) > 2 else float(lo_ext)
        orig_hi = float(np.expm1(hi_ext) - shift) if abs(skew) > 2 else float(hi_ext)
        exp_range = f'[{orig_lo:.2f}, {orig_hi:.2f}]'
        for idx in flagged.index:
            orig_val = float(base.loc[idx])
            dev = vals.loc[idx]
            lo4 = q1 - 4*iqr; hi4 = q3 + 4*iqr
            lo5 = q1 - 5*iqr; hi5 = q3 + 5*iqr
            if dev > hi5 or dev < lo5:
                sev = 'critical'
            elif dev > hi4 or dev < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': orig_val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {orig_val:.2f} lies outside expected range {exp_range}'
            })
            if len(anomaly_records) >= 25:
                break
        if len(anomaly_records) >= 25:
            break
    result['anomalies'] = anomaly_records[:25]
except Exception:
    pass

