    import numpy as np
    df_trend = sale_return_rows.copy()
    df_trend['Wk_End_Dt'] = pd.to_datetime(df_trend['Wk_End_Dt'])
    weekly = df_trend.groupby('Wk_End_Dt')[['Net Sales', 'COGS']].sum()
