            last_val = float(rolled.iloc[-1])
            pct = round((last_val - first_val) / abs(first_val) * 100, 2) if first_val != 0 else 0.0
            direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
            result['trends'].append({
