    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

import numpy as np
from scipy import stats

# ── masks ──────────────────────────────────────────────────────────────────
sale_mask   = df['row_kind'] == 'sale'
return_mask = df['row_kind'] == 'return'
net_mask    = sale_mask | return_mask

df_sale = df[sale_mask].copy()
df_ret  = df[return_mask].copy()
df_net  = df[net_mask].copy()

# inline revenue helpers (never stored as a result column name)
df_sale['_rev']  = df_sale['Quantity'] * df_sale['UnitPrice']
df_ret['_rev']   = df_ret['Quantity']  * df_ret['UnitPrice']
df_net['_rev']   = df_net['Quantity']  * df_net['UnitPrice']

# ── EDA ────────────────────────────────────────────────────────────────────
try:
    for col in ['Quantity', 'UnitPrice']:
        s = df_sale[col].dropna()
        result['eda_summary'][col] = {
            'mean':   round(float(s.mean()),   4),
            'std':    round(float(s.std()),    4),
            'min':    round(float(s.min()),    4),
            'max':    round(float(s.max()),    4),
            'median': round(float(s.median()), 4),
            'count':  int(s.count()),
        }
except Exception:
    pass

# ── CORRELATIONS ───────────────────────────────────────────────────────────
try:
    num_df = df_sale[['Quantity', 'UnitPrice']].dropna()
    if len(num_df) > 1:
        r, _ = stats.pearsonr(num_df['Quantity'], num_df['UnitPrice'])
        if abs(r) >= 0.2:
            result['correlations']['Quantity__UnitPrice'] = round(float(r), 4)
except Exception:
    pass

# ── SEGMENTATION ───────────────────────────────────────────────────────────
try:
    # mean Quantity & UnitPrice by Country (top 10 by row count)
    for metric in ['Quantity', 'UnitPrice']:
        for seg in ['Country', 'Description']:
            top = df_sale.groupby(seg)[metric].count().nlargest(10).index
            grp = df_sale[df_sale[seg].isin(top)].groupby(seg)[metric].mean().sort_values(ascending=False)
            result['segments'].append({
                'segment_column': seg, 'metric_column': metric,
                'aggregation': 'mean', 'label': None,
                'results': [{'name': str(k), 'value': round(float(v), 4)} for k, v in grp.items()]
            })

    # net_sales (sum of Quantity*UnitPrice) by Country — top 10
    top_c = df_sale.groupby('Country')['_rev'].sum().nlargest(10).index
    net_by_c = df_net[df_net['Country'].isin(top_c)].groupby('Country')['_rev'].sum().sort_values(ascending=False)
    result['segments'].append({
        'segment_column': 'Country', 'metric_column': 'Quantity',
        'aggregation': 'sum', 'label': 'net_sales_by_country',
        'results': [{'name': str(k), 'value': round(float(v), 2)} for k, v in net_by_c.items()]
    })

    # return_rate by Country: |return rev| / gross sale rev
    gross_c = df_sale.groupby('Country')['_rev'].sum()
    ret_c   = df_ret.groupby('Country')['_rev'].apply(lambda x: x.abs().sum())
    top_c10 = gross_c.nlargest(10).index
    rr_rows = []
    for c in top_c10:
        g = gross_c.get(c, 0.0)
        r_val = float(ret_c.get(c, 0.0))
        rr_rows.append({'name': str(c), 'value': round(r_val / g, 4) if g > 0 else 0.0})
    result['segments'].append({
        'segment_column': 'Country', 'metric_column': 'Quantity',
        'aggregation': 'ratio', 'label': 'return_rate',
        'results': rr_rows
    })
except Exception:
    pass

# ── ANOMALIES ──────────────────────────────────────────────────────────────
try:
    total_flags = 0
    for col in ['Quantity', 'UnitPrice']:
        if total_flags >= 25:
            break
        s = df_sale[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0.0, -float(s.min()))
            s_t = np.log1p(s + shift)
        else:
            s_t, shift = s.copy(), 0.0
        q1, q3 = float(s_t.quantile(0.25)), float(s_t.quantile(0.75))
        iqr = q3 - q1
        lo3, hi3 = q1 - 3*iqr, q3 + 3*iqr
        flagged = s_t[(s_t < lo3) | (s_t > hi3)]
        if len(flagged) / len(s_t) > 0.05:
            result['anomalies'].append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': 'heavy-tailed',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme values are a natural distribution pattern, not individually flagged.'
            })
            continue
        lo_orig = float(np.expm1(lo3) - shift) if abs(skew) > 2 else lo3
        hi_orig = float(np.expm1(hi3) - shift) if abs(skew) > 2 else hi3
        exp_range = f'[{lo_orig:.2f}, {hi_orig:.2f}]'
        lo4, hi4 = q1 - 4*iqr, q3 + 4*iqr
        lo5, hi5 = q1 - 5*iqr, q3 + 5*iqr
        for idx in flagged.index:
            if total_flags >= 25:
                break
            raw = float(df_sale.loc[idx, col])
            tv  = float(s_t.loc[idx])
            sev = 'critical' if (tv < lo5 or tv > hi5) else ('high' if (tv < lo4 or tv > hi4) else 'medium')
            result['anomalies'].append({
                'column': col, 'row_index': int(idx), 'value': raw,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {raw} lies outside expected range {exp_range}.'
            })
            total_flags += 1
except Exception:
    pass

# ── TRENDS ─────────────────────────────────────────────────────────────────
try:
    df_sale['InvoiceDate'] = pd.to_datetime(df_sale['InvoiceDate'], errors='coerce')
    df_sale['_month'] = df_sale['InvoiceDate'].dt.to_period('M')

    for col in ['Quantity', 'UnitPrice']:
        agg = 'sum' if col == 'Quantity' else 'mean'
        monthly = df_sale.groupby('_month')[col].agg(agg).sort_index()
        if len(monthly) >= 2:
            pct = float((monthly.iloc[-1] - monthly.iloc[0]) / abs(monthly.iloc[0]) * 100) if monthly.iloc[0] != 0 else 0.0
            direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
            result['trends'].append({
                'column': col, 'period': 'MoM', 'direction': direction,
                'pct_change': round(pct, 2), 'segment': None
            })

    # 7-day rolling on Quantity (units sold)
    df_sale_ts = df_sale.set_index('InvoiceDate').sort_index()
    daily_qty  = df_sale_ts['Quantity'].resample('D').sum()
    roll7      = daily_qty.rolling(7).mean().dropna()
    if len(roll7) >= 2:
        pct7 = float((roll7.iloc[-1] - roll7.iloc[0]) / abs(roll7.iloc[0]) * 100) if roll7.iloc[0] != 0 else 0.0
        dir7 = 'up' if pct7 > 1 else ('down' if pct7 < -1 else 'flat')
        result['trends'].append({
            'column': 'Quantity', 'period': '7d_rolling', 'direction': dir7,
            'pct_change': round(pct7, 2), 'segment': None
        })
except Exception:
    pass

# ── FORECASTING (OLS linear extrapolation on monthly Quantity totals) ───────
try:
    monthly_qty = df_sale.groupby('_month')['Quantity'].sum().sort_index()
    if len(monthly_qty) >= 3:
        x = np.arange(len(monthly_qty), dtype=float)
        y = monthly_qty.values.astype(float)
        slope, intercept, *_ = stats.linregress(x, y)
        for step, label in enumerate([1, 2], start=1):
            period_str = (monthly_qty.index[-1] + step).strftime('%Y-%m')
            fval = round(float(slope * (len(monthly_qty) - 1 + step) + intercept), 2)
            result['forecast_points'].append({'period': period_str, 'value': fval})
except Exception:
    pass

# ── ASSUMPTIONS ────────────────────────────────────────────────────────────
result['assumptions'] = [
    'UnitPrice already coerced to float64 by cleaning step; currency symbols removed.',
    'Only sale rows used for EDA, segmentation, trends, and forecasting.',
    'Net sales and return_rate computed inline from Quantity * UnitPrice; not stored as a separate column.',
    'Anomaly detection uses log1p transform when |skew| > 2; boundaries converted back to original units.',
    'Forecasting uses OLS linear regression on monthly Quantity totals; two periods ahead.'
]

# ─── Standard statistics (deterministic) ───
result['builtin'] = []
_targets, _segs, _date, _hints = ['Quantity', 'UnitPrice'], ['Description', 'Country'], 'InvoiceDate', {}
try:
    if True:
        for _i, _a in enumerate(_targets):
            for _b in _targets[_i + 1:]:
                if f'{_a}__{_b}' not in result['correlations'] and f'{_b}__{_a}' not in result['correlations']:
                    _r = df[_a].corr(df[_b])
                    if _r == _r:
                        result['correlations'][f'{_a}__{_b}'] = round(float(_r), 4)
                        result['builtin'].append(f'corr:{_a}__{_b}')
except Exception:
    pass
try:
    if (_date or _hints) and True:
        # A mid-month export compares the last two complete months (agents.utils.partial_last_month).
        def _cut(_t):
            _mm = _t.dt.to_period('M')
            _d = _t.dropna()
            if _d.empty:
                return _mm
            _days = _d.dt.normalize().groupby(_d.dt.to_period('M')).nunique().sort_index()
            _g = _d.dt.normalize().drop_duplicates().sort_values().diff().dt.days.dropna()
            _regular = len(_g) >= 3 and _g.std() <= 0.25 * _g.mean()
            if len(_days) >= 3 and _d.max().normalize() < _d.max().normalize() + pd.offsets.MonthEnd(0) and (_days.iloc[:-1].median() >= 4 or _regular) and _days.iloc[-1] < 0.9 * _days.iloc[:-1].median():
                _mm = _mm.where(_mm != _days.index[-1])
            return _mm
        _month = _cut(pd.to_datetime(df[_date], errors='coerce')) if _date else pd.Series(pd.NaT, index=df.index).dt.to_period('M')
        def _level_months(_tc):
            return _cut(pd.to_datetime(df[_tc], format='mixed', errors='coerce'))
        # One definition of MoM (calendar-month totals), so the built-in value replaces the model's.
        result['trends'] = [t for t in result['trends'] if not (isinstance(t, dict) and t.get('period') == 'MoM' and t.get('column') in _targets)]
        # ponytail: values all in [0, 1] → a rate or flag, compared by month mean; anything else
        # by month total. A semantic layer (Phase 4) can declare the aggregation instead.
        # The semantic layer, when it matched (Phase 5.5): a level (balance, MRR) is each entity's
        # last value in the month, summed; a reading is a mean.
        # Weekly flows (POS week endings): each month is its average week, so 4- and 5-week months
        # compare fairly (agents.utils.weekly_cadence).
        _dd = pd.to_datetime(df[_date], errors='coerce').dropna().drop_duplicates().sort_values() if _date else pd.Series(dtype='datetime64[ns]')
        _weekly = True and len(_dd) >= 4 and _dd.diff().dt.days.median() == 7
        # a domain's money columns count sale and return rows in the main currency (as its tiles)
        _money, _kind = [], 'row_kind'
        def _mom(_frame, _col):
            _h = _hints.get(_col)
            _agg = _h[0] if _h else ('mean' if df[_col].dropna().between(0, 1).all() else 'sum')
            _mon = _month
            if _agg in ('last', 'first'):
                if not _h[1] or not all(_e in df.columns for _e in _h[1]) or _h[2] not in df.columns:
                    return None, 0   # its account (or time) column is gone: no total, never a sum
                _mon = _level_months(_h[2])   # the level's own months, partial last month out
                _f = _frame.assign(_t=pd.to_datetime(_frame[_h[2]], format='mixed', errors='coerce'),
                                   _m=_mon.loc[_frame.index])
                _f = _f.dropna(subset=['_m', '_t', _col]).sort_values('_t', kind='stable')
                _tot = _f.groupby(['_m', *_h[1]])[_col].agg(_agg).groupby(level=0).sum().sort_index()
            else:
                if _col in _money and _kind in _frame.columns:
                    _frame = _frame[_frame[_kind].isin(['sale', 'return'])]
                _tot = _frame.groupby(_month.loc[_frame.index])[_col].agg(_agg).sort_index()
                if _weekly and _agg == 'sum':
                    _tot = _tot / _frame.groupby(_month.loc[_frame.index])[_date].nunique().reindex(_tot.index)
                    if 'weekly' not in ' '.join(result['assumptions']):
                        result['assumptions'].append('Weekly data: each month is compared as its average week (months have 4 or 5 week-endings).')
            if len(_tot) < 2 or _tot.iloc[-2] == 0:
                return None, 0
            _last2 = _mon.loc[_frame.index].isin(_tot.index[-2:])
            _n = int(_frame.loc[_last2, _col].notna().sum())
            return round(float((_tot.iloc[-1] / _tot.iloc[-2] - 1) * 100), 2), _n
        for _c in _targets:
            _jobs = [(None, df)]
            if _segs:
                _top = df[_segs[0]].value_counts().head(10).index
                _jobs += [(str(_v), df[df[_segs[0]] == _v]) for _v in _top]
            for _seg, _frame in _jobs:
                _p, _n = _mom(_frame, _c)
                if _p is not None:
                    result['trends'].append({'column': _c, 'period': 'MoM', 'pct_change': _p, 'segment': _seg, 'n': _n,
                                             'direction': 'up' if _p > 0 else 'down' if _p < 0 else 'flat'})
                    result['builtin'].append(f'trend:{_c}' + (f' ({_seg})' if _seg else '') + ':MoM')
except Exception:
    pass
try:
    if len(_segs) >= 2 and 'segmentation' in ['anomaly', 'correlation', 'eda', 'forecasting', 'segmentation', 'trend']:
        _joint = '|'.join(_segs[:2])
        for _c in _targets:
            if any(s.get('segment_column') == _joint and s.get('metric_column') == _c for s in result['segments'] if isinstance(s, dict)):
                continue
            _g = df.groupby(_segs[:2])[_c].mean()
            _n = df.groupby(_segs[:2]).size().sort_values(ascending=False).head(20).index
            result['segments'].append({'segment_column': _joint, 'metric_column': _c, 'aggregation': 'mean',
                                       'results': [{'name': f'{_a}|{_b}', 'value': round(float(_g[(_a, _b)]), 4)} for _a, _b in _n]})
            result['builtin'].append(f'seg:{_joint}/{_c}')
except Exception:
    pass


